#include <bits/stdc++.h>
using namespace std;

int n;
vector<vector<int>> g;

// BFS from root; returns (last vertex reached, its distance) = a farthest vertex.
pair<int, int> farthest(int root) {
    vector<int> dist(n, -1), queue{root};
    dist[root] = 0;
    for (size_t h = 0; h < queue.size(); h++) {
        int u = queue[h];
        for (int v : g[u])
            if (dist[v] < 0) { dist[v] = dist[u] + 1; queue.push_back(v); }
    }
    return {queue.back(), dist[queue.back()]};
}

int main() {
    if (scanf("%d", &n) != 1) return 0;
    g.assign(n, {});
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        g[u - 1].push_back(v - 1);
        g[v - 1].push_back(u - 1);
    }
    int u = farthest(0).first;
    int diameter = farthest(u).second;
    printf("%d\n", (diameter + 1) / 2);
}

import java.io.*;
import java.util.*;

public class Main {
    static int n;
    static int[] head, nxt, to;

    // BFS from root; returns {last vertex reached, its distance} = a farthest vertex.
    static int[] farthest(int root) {
        int[] dist = new int[n], queue = new int[n];
        Arrays.fill(dist, -1);
        dist[root] = 0;
        int qh = 0, qt = 0;
        queue[qt++] = root;
        while (qh < qt) {
            int u = queue[qh++];
            for (int e = head[u]; e >= 0; e = nxt[e]) {
                int v = to[e];
                if (dist[v] < 0) { dist[v] = dist[u] + 1; queue[qt++] = v; }
            }
        }
        int last = queue[qt - 1];
        return new int[] {last, dist[last]};
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken();
        n = (int) st.nval;
        head = new int[n];
        Arrays.fill(head, -1);
        nxt = new int[2 * n];
        to = new int[2 * n];
        int m = 0;
        for (int i = 0; i < n - 1; i++) {
            st.nextToken();
            int u = (int) st.nval - 1;
            st.nextToken();
            int v = (int) st.nval - 1;
            to[m] = v; nxt[m] = head[u]; head[u] = m++;
            to[m] = u; nxt[m] = head[v]; head[v] = m++;
        }
        int u = farthest(0)[0];
        int diameter = farthest(u)[1];
        System.out.println((diameter + 1) / 2);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	nextInt := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	n := nextInt()
	g := make([][]int, n)
	for i := 0; i < n-1; i++ {
		u, v := nextInt()-1, nextInt()-1
		g[u] = append(g[u], v)
		g[v] = append(g[v], u)
	}
	// BFS from root; returns the last vertex reached (a farthest one) and its distance.
	farthest := func(root int) (int, int) {
		dist := make([]int, n)
		for i := range dist {
			dist[i] = -1
		}
		dist[root] = 0
		queue := []int{root}
		for h := 0; h < len(queue); h++ {
			u := queue[h]
			for _, v := range g[u] {
				if dist[v] < 0 {
					dist[v] = dist[u] + 1
					queue = append(queue, v)
				}
			}
		}
		last := queue[len(queue)-1]
		return last, dist[last]
	}
	u, _ := farthest(0)
	_, diameter := farthest(u)
	fmt.Println((diameter + 1) / 2)
}
